import type { NumericRow, SpikeSettings } from './records.ts';

export type Reason = 'absent' | 'na' | 'flat' | 'spike';
export interface PreliminaryRow extends NumericRow {
  preliminary: number;
}
export interface FlatRun {
  start: number;
  end: number;
  value: number;
}
export interface Spike {
  time: number;
  value: number;
  residual: number;
  median: number;
  mad: number;
  limit: number;
}
export function median(sorted: number[]): number {
  const m = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[m] : (sorted[m - 1] + sorted[m]) / 2;
}
export function flatRuns(rows: NumericRow[], minimum: number): FlatRun[] {
  const runs: FlatRun[] = [];
  for (let a = 0; a < rows.length;) {
    let b = a;
    while (
      b + 1 < rows.length &&
      rows[b + 1].time === rows[b].time + 1 &&
      rows[b + 1].milli === rows[a].milli
    ) {
      b++;
    }
    if (b - a + 1 >= minimum) {
      runs.push({ start: rows[a].time, end: rows[b].time, value: rows[a].value });
    }
    a = b + 1;
  }
  return runs;
}
function lowerBound(values: number[], target: number): number {
  let lo = 0;
  let hi = values.length;
  while (lo < hi) {
    const m = Math.floor((lo + hi) / 2);
    if (values[m] < target) lo = m + 1;
    else hi = m;
  }
  return lo;
}
function mad(sorted: number[], center: number): number {
  let right = lowerBound(sorted, center);
  let left = right - 1;
  let previous = 0;
  let current = 0;
  for (let i = 0; i <= Math.floor(sorted.length / 2); i++) {
    previous = current;
    const a = left >= 0 ? Math.abs(sorted[left] - center) : Infinity;
    const b = right < sorted.length ? Math.abs(sorted[right] - center) : Infinity;
    if (a <= b) {
      current = a;
      left--;
    } else {
      current = b;
      right++;
    }
  }
  return sorted.length % 2 ? current : (previous + current) / 2;
}
export function spikeTests(
  rows: PreliminaryRow[],
  settings: SpikeSettings,
): { tested: number; spikes: Spike[] } {
  const sorted: number[] = [];
  const spikes: Spike[] = [];
  let left = 0;
  let right = 0;
  let tested = 0;
  for (const row of rows) {
    while (right < rows.length && rows[right].time <= row.time + settings.window) {
      const value = rows[right++].preliminary;
      sorted.splice(lowerBound(sorted, value), 0, value);
    }
    while (left < right && rows[left].time < row.time - settings.window) {
      const value = rows[left++].preliminary;
      sorted.splice(lowerBound(sorted, value), 1);
    }
    if (sorted.length < settings.count) continue;
    tested++;
    const center = median(sorted);
    const deviation = mad(sorted, center);
    const limit = Math.max(settings.factor * 1.4826 * deviation, settings.minimum);
    if (Math.abs(row.preliminary - center) > limit) {
      spikes.push({
        time: row.time,
        value: row.value,
        residual: row.preliminary,
        median: center,
        mad: deviation,
        limit,
      });
    }
  }
  return { tested, spikes };
}
export function gaps(
  first: number,
  last: number,
  reasons: Map<number, Reason>,
): { start: number; end: number; cause: Reason | 'mixed' }[] {
  const result: { start: number; end: number; cause: Reason | 'mixed' }[] = [];
  for (let time = first; time <= last;) {
    if (!reasons.has(time)) {
      time++;
      continue;
    }
    const start = time;
    let cause: Reason | 'mixed' = reasons.get(time)!;
    while (time <= last && reasons.has(time)) {
      if (reasons.get(time) !== cause) cause = 'mixed';
      time++;
    }
    result.push({ start, end: time - 1, cause });
  }
  return result;
}

import type { Constituent } from './records.ts';

export const PI = 3.141592653589793;
export interface FitConstituent extends Constituent {
  a: number;
  b: number;
  amplitude: number;
  phase: number;
}
export interface Model {
  mean: number;
  unknowns: number;
  coefficients: number[];
  inverse: number[][];
  constituents: FitConstituent[];
}
export interface FitRow {
  time: number;
  value: number;
}
export function angle(speed: number, time: number): number {
  const d = speed * time;
  const d2 = d - 360 * Math.floor(d / 360);
  return (d2 * PI) / 180;
}
export function regressors(constituents: Constituent[], time: number): number[] {
  const x = [1];
  for (const c of constituents) {
    const theta = angle(c.speed, time);
    x.push(Math.cos(theta), Math.sin(theta));
  }
  return x;
}
export function normalEquations(
  rows: FitRow[],
  constituents: Constituent[],
): { matrix: number[][]; rhs: number[] } {
  const p = 2 * constituents.length + 1;
  const matrix: number[][] = Array.from({ length: p }, () => Array(p).fill(0));
  const rhs: number[] = Array(p).fill(0);
  for (const row of rows) {
    const x = regressors(constituents, row.time);
    for (let i = 0; i < p; i++) {
      for (let j = 0; j < p; j++) matrix[i][j] += x[i] * x[j];
      rhs[i] += x[i] * row.value;
    }
  }
  return { matrix, rhs };
}
export function solve(
  matrix: number[][],
  rhs: number[],
): { coefficients: number[]; inverse: number[][] } {
  const p = rhs.length;
  const m = matrix.map((row, i) =>
    row.concat(
      rhs[i],
      Array.from({ length: p }, (_, j) => (i === j ? 1 : 0)),
    ),
  );
  const inverse: number[][] = Array.from({ length: p }, () => Array(p));
  let coefficients: number[] = [];
  for (let j = 0; j < p; j++) {
    let pivot = j;
    for (let i = j + 1; i < p; i++) if (Math.abs(m[i][j]) > Math.abs(m[pivot][j])) pivot = i;
    if (pivot !== j) [m[pivot], m[j]] = [m[j], m[pivot]];
    for (let i = j + 1; i < p; i++) {
      const factor = m[i][j] / m[j][j];
      for (let c = j; c <= 2 * p; c++) m[i][c] = m[i][c] - factor * m[j][c];
    }
  }
  for (let c = p; c <= 2 * p; c++) {
    const solution: number[] = Array(p);
    for (let i = p - 1; i >= 0; i--) {
      let s = m[i][c];
      for (let j = i + 1; j < p; j++) s = s - m[i][j] * solution[j];
      solution[i] = s / m[i][i];
    }
    if (c === p) coefficients = solution;
    else for (let i = 0; i < p; i++) inverse[i][c - p - 1] = solution[i];
  }
  return { coefficients, inverse };
}
export function fit(rows: FitRow[], constituents: Constituent[]): Model {
  const { matrix, rhs } = normalEquations(rows, constituents);
  const { coefficients, inverse } = solve(matrix, rhs);
  const fitted = constituents.map((c, i) => {
    const a = coefficients[2 * i + 1];
    const b = coefficients[2 * i + 2];
    const amplitude = Math.sqrt(a * a + b * b);
    let phase = (Math.atan2(b, a) * 180) / PI;
    if (phase < 0) phase += 360;
    return { ...c, a, b, amplitude, phase };
  });
  return {
    mean: coefficients[0],
    unknowns: coefficients.length,
    coefficients,
    inverse,
    constituents: fitted,
  };
}

import {
  readAll,
  datetime,
  hourDatetime,
  date,
  type Parameters,
  type Constituent,
  type Station,
  type Observation,
  type NumericRow,
} from './records.ts';
import { flatRuns, spikeTests, gaps, type Reason, type PreliminaryRow } from './cleaning.ts';
import { fit, PI, type FitConstituent } from './harmonic_fit.ts';
import { level, gridExtrema, type GridExtremum } from './predict.ts';
import { real as f, plotLines, writeFiles } from './report.ts';

interface ResidualRow extends PreliminaryRow {
  fitted: number;
  residual: number;
}
interface Extremum extends GridExtremum {
  minute: number;
  day: number;
  label: 'HHW' | 'LHW' | 'HLW' | 'LLW';
}
interface Daily {
  day: number;
  highCount: number;
  lowCount: number;
  hhw: number | null;
  llw: number | null;
  range: number | null;
}
interface Surge {
  type: 'positive' | 'negative';
  start: number;
  end: number;
  peak: number;
  peakTime: number;
}
interface EstimatedConstituent extends FitConstituent {
  amplitudeError: number;
  phaseError: number;
  snr: number;
  significant: string;
}
type Cleaned = ReturnType<typeof checkStation>;
type Fitted = ReturnType<typeof finalFit>;
type Predicted = ReturnType<typeof predictions>;
type StationResult = ReturnType<typeof analyzeStation>;
function sum(values: number[]): number {
  let total = 0;
  for (const value of values) total += value;
  return total;
}
const mean = (values: number[]): number => sum(values) / values.length;
function choose<T>(items: T[], value: (item: T) => number, largest = true): T | null {
  let best: T | null = null;
  for (const item of items) {
    if (best === null || (largest ? value(item) > value(best) : value(item) < value(best))) {
      best = item;
    }
  }
  return best;
}
function selectConstituents(constituents: Constituent[], length: number, rayleigh: number) {
  const selected: Constituent[] = [];
  const statuses = new Map<string, string>();
  for (const c of constituents) {
    if (c.speed * length < 360 * rayleigh) {
      statuses.set(c.name, 'short');
      continue;
    }
    const conflict = selected.find(
      (other) => Math.abs(c.speed - other.speed) * length < 360 * rayleigh,
    );
    if (conflict) statuses.set(c.name, 'conflict:' + conflict.name);
    else {
      statuses.set(c.name, 'fitted');
      selected.push(c);
    }
  }
  return { selected, statuses };
}
function checkStation(
  station: Station,
  rows: Observation[],
  constituents: Constituent[],
  params: Parameters,
) {
  const numeric = rows.filter((row): row is NumericRow => row.value !== null);
  const first = numeric[0].time;
  const last = numeric.at(-1)!.time;
  const length = last - first;
  const byTime = new Map(rows.map((row) => [row.time, row]));
  const reasons = new Map<number, Reason>();
  for (let t = first; t <= last; t++) {
    if (!byTime.has(t)) reasons.set(t, 'absent');
    else if (byTime.get(t)!.value === null) reasons.set(t, 'na');
  }
  const flats = flatRuns(numeric, params.flatRun);
  for (const run of flats) for (let t = run.start + 1; t <= run.end; t++) reasons.set(t, 'flat');
  const candidateRows = numeric.filter((row) => !reasons.has(row.time));
  const selection = selectConstituents(constituents, length, params.rayleigh);
  const preliminary = fit(candidateRows, selection.selected);
  const candidates = candidateRows.map((row) => ({
    ...row,
    preliminary: row.value - level(preliminary, row.time),
  }));
  const prefitRms = Math.sqrt(
    sum(candidates.map((row) => row.preliminary * row.preliminary)) / candidates.length,
  );
  const { tested, spikes } = spikeTests(candidates, params.spike);
  for (const spike of spikes) reasons.set(spike.time, 'spike');
  const usable = candidates.filter((row) => !reasons.has(row.time));
  const counts = {
    rows: rows.length,
    numeric: numeric.length,
    na: 0,
    absent: 0,
    flat: 0,
    spikes: 0,
    usable: usable.length,
  };
  for (const reason of reasons.values()) counts[reason === 'spike' ? 'spikes' : reason]++;
  return {
    ...station,
    first,
    last,
    length,
    selection,
    candidates,
    usable,
    counts,
    flats,
    prefitRms,
    tested,
    spikes,
    gaps: gaps(first, last, reasons),
  };
}
function finalFit(station: Cleaned, params: Parameters) {
  const model = fit(station.usable, station.selection.selected);
  const residuals = new Map<number, number>();
  let squares = 0;
  let maxAbs = 0;
  const usable: ResidualRow[] = station.usable.map((row) => {
    const fitted = level(model, row.time);
    const residual = row.value - fitted;
    residuals.set(row.time, residual);
    squares += residual * residual;
    maxAbs = Math.max(maxAbs, Math.abs(residual));
    return { ...row, fitted, residual };
  });
  const dof = usable.length - model.unknowns;
  const variance = squares / dof;
  const observedMean = mean(usable.map((row) => row.value));
  let centeredSquares = 0;
  let lagProduct = 0;
  let lagSquares = 0;
  for (const row of usable) {
    const difference = row.value - observedMean;
    centeredSquares += difference * difference;
    if (residuals.has(row.time + 1)) {
      lagProduct += row.residual * residuals.get(row.time + 1)!;
      lagSquares += row.residual * row.residual;
    }
  }
  const fittedConstituents = new Map<string, EstimatedConstituent>(
    model.constituents.map((c, i): [string, EstimatedConstituent] => {
      const { a, b, amplitude } = c;
      const ia = 2 * i + 1;
      const ib = 2 * i + 2;
      const va = variance * model.inverse[ia][ia];
      const vb = variance * model.inverse[ib][ib];
      const cab = variance * model.inverse[ia][ib];
      const amplitudeError = Math.sqrt(a * a * va + b * b * vb + 2 * a * b * cab) / amplitude;
      const phaseError =
        ((Math.sqrt(b * b * va + a * a * vb - 2 * a * b * cab) / (amplitude * amplitude)) * 180) /
        PI;
      const ratio = amplitude / amplitudeError;
      const snr = ratio * ratio;
      return [
        c.name,
        { ...c, amplitudeError, phaseError, snr, significant: snr >= params.snrMin ? 'yes' : 'no' },
      ];
    }),
  );
  const statistics = {
    dof,
    rms: Math.sqrt(squares / usable.length),
    maxAbs,
    explained: 100 * (1 - squares / centeredSquares),
    lag1: lagProduct / lagSquares,
  };
  const top = usable
    .toSorted((a, b) => Math.abs(b.residual) - Math.abs(a.residual) || a.time - b.time)
    .slice(0, params.topResiduals);
  return { ...station, usable, model, fittedConstituents, residuals, statistics, top };
}
function predictions(station: Fitted, params: Parameters) {
  const hourly = Array.from({ length: params.hours + 1 }, (_, i) =>
    level(station.model, params.start + i),
  );
  const raw = gridExtrema(station.model, params.start, params.hours, params.grid);
  const rawExtrema = raw.length;
  while (raw.length >= 2) {
    let pair = 0;
    let difference = Math.abs(raw[0].height - raw[1].height);
    for (let i = 1; i + 1 < raw.length; i++) {
      const candidate = Math.abs(raw[i].height - raw[i + 1].height);
      if (candidate < difference) {
        difference = candidate;
        pair = i;
      }
    }
    if (difference >= params.minRange) break;
    raw.splice(pair, 2);
  }
  const extrema: Extremum[] = raw.map((e) => {
    const minute = Math.floor(e.refinedMinute + 0.5);
    return {
      ...e,
      minute,
      day: Math.floor(minute / 1440),
      label: e.kind === 'high' ? 'LHW' : 'HLW',
    };
  });
  const byDay = new Map<number, { highs: Extremum[]; lows: Extremum[] }>();
  for (const e of extrema) {
    let group = byDay.get(e.day);
    if (!group) {
      group = { highs: [], lows: [] };
      byDay.set(e.day, group);
    }
    group[e.kind === 'high' ? 'highs' : 'lows'].push(e);
  }
  for (const group of byDay.values()) {
    const high = choose(group.highs, (e) => e.height);
    const low = choose(group.lows, (e) => e.height, false);
    if (high) high.label = 'HHW';
    if (low) low.label = 'LLW';
  }
  const daily: Daily[] = [];
  for (let offset = 0; offset < params.hours / 24; offset++) {
    const day = params.start / 24 + offset;
    const group = byDay.get(day) ?? { highs: [], lows: [] };
    const high = choose(group.highs, (e) => e.height);
    const low = choose(group.lows, (e) => e.height, false);
    const hhw = high?.height ?? null;
    const llw = low?.height ?? null;
    daily.push({
      day,
      highCount: group.highs.length,
      lowCount: group.lows.length,
      hhw,
      llw,
      range: hhw === null || llw === null ? null : hhw - llw,
    });
  }
  return {
    ...station,
    predictions: hourly,
    rawExtrema,
    extrema,
    highs: extrema.filter((e) => e.kind === 'high'),
    lows: extrema.filter((e) => e.kind === 'low'),
    daily,
  };
}
function validation(station: Fitted, constituents: Constituent[], params: Parameters) {
  const split = station.first + Math.floor(station.length / 2);
  const training = station.usable.filter((row) => row.time <= split);
  const test = station.usable.filter((row) => row.time > split);
  const selection = selectConstituents(
    constituents,
    training.at(-1)!.time - training[0].time,
    params.rayleigh,
  );
  const model = fit(training, selection.selected);
  const observedMean = mean(test.map((row) => row.value));
  let squares = 0;
  let inSample = 0;
  let centeredSquares = 0;
  for (const row of test) {
    const error = row.value - level(model, row.time);
    const centered = row.value - observedMean;
    squares += error * error;
    inSample += row.residual * row.residual;
    centeredSquares += centered * centered;
  }
  return {
    split,
    train: training.length,
    test: test.length,
    constituents: selection.selected.length,
    rms: Math.sqrt(squares / test.length),
    inSampleRms: Math.sqrt(inSample / test.length),
    skill: 1 - squares / centeredSquares,
  };
}
function residualEvents(station: Fitted, settings: Parameters['surge']): Surge[] {
  const events: Surge[] = [];
  let current: Surge | null = null;
  const finish = (): void => {
    if (current !== null && current.end - current.start + 1 >= settings.hours) events.push(current);
    current = null;
  };
  for (const row of station.usable) {
    const type =
      row.residual > settings.threshold
        ? 'positive'
        : row.residual < -settings.threshold
          ? 'negative'
          : null;
    if (current !== null && (type !== current.type || row.time !== current.end + 1)) finish();
    if (type === null) continue;
    if (current === null) {
      current = { type, start: row.time, end: row.time, peak: row.residual, peakTime: row.time };
    } else {
      current.end = row.time;
      if (type === 'positive' ? row.residual > current.peak : row.residual < current.peak) {
        current.peak = row.residual;
        current.peakTime = row.time;
      }
    }
  }
  finish();
  return events;
}
function dailyMeans(station: Fitted) {
  const weights = [0, 2, 1, 1, 2, 0, 1, 1, 0, 2, 0, 1, 1, 0, 1, 0, 0, 1, 0, 1];
  const usable = new Map(station.usable.map((row) => [row.time, row.value]));
  const filledLevels: number[] = [];
  for (let t = station.first; t <= station.last; t++) {
    filledLevels.push(usable.has(t) ? usable.get(t)! : level(station.model, t));
  }
  const days: { day: number; level: number; filled: number }[] = [];
  for (let day = Math.floor(station.first / 24); day <= Math.floor(station.last / 24); day++) {
    const noon = day * 24 + 12;
    if (noon - 19 < station.first || noon + 19 > station.last) continue;
    let total = 0;
    let filled = 0;
    for (let j = -19; j <= 19; j++) {
      const time = noon + j;
      total += weights[Math.abs(j)] * filledLevels[time - station.first];
      if (!usable.has(time)) filled++;
    }
    days.push({ day, level: total / 30, filled });
  }
  const average = mean(days.map((d) => d.level));
  const firstDay = days[0].day;
  const meanDay = mean(days.map((d) => d.day - firstDay));
  let numerator = 0;
  let denominator = 0;
  for (const d of days) {
    const x = d.day - firstDay - meanDay;
    numerator += x * (d.level - average);
    denominator += x * x;
  }
  return {
    days,
    average,
    slope: 1000 * (numerator / denominator),
    maximum: choose(days, (d) => d.level)!,
    minimum: choose(days, (d) => d.level, false)!,
  };
}
function tidalCharacteristics(station: Predicted, params: Parameters) {
  const m2 = station.fittedConstituents.get('M2')!;
  const s2 = station.fittedConstituents.get('S2')!;
  const k1 = station.fittedConstituents.get('K1')!;
  const o1 = station.fittedConstituents.get('O1')!;
  const m4 = station.fittedConstituents.get('M4')!;
  const form = (k1.amplitude + o1.amplitude) / (m2.amplitude + s2.amplitude);
  const type =
    form < 0.25
      ? 'semidiurnal'
      : form < 1.5
        ? 'mixed_semidiurnal'
        : form < 3
          ? 'mixed_diurnal'
          : 'diurnal';
  const mhhw = mean(station.daily.filter((d) => d.hhw !== null).map((d) => d.hhw!));
  const mllw = mean(station.daily.filter((d) => d.llw !== null).map((d) => d.llw!));
  const mhw = mean(station.highs.map((e) => e.height));
  const mlw = mean(station.lows.map((e) => e.height));
  const amplitudes = sum(station.model.constituents.map((c) => c.amplitude));
  const complete = station.daily.filter((d) => d.range !== null);
  const rises: number[] = [];
  const falls: number[] = [];
  for (let i = 1; i < station.extrema.length; i++) {
    const a = station.extrema[i - 1];
    const b = station.extrema[i];
    if (a.kind === 'low' && b.kind === 'high') rises.push(b.minute - a.minute);
    if (a.kind === 'high' && b.kind === 'low') falls.push(b.minute - a.minute);
  }
  let relativePhase = 2 * m2.phase - m4.phase;
  while (relativePhase < 0) relativePhase += 360;
  while (relativePhase >= 360) relativePhase -= 360;
  const above = station.predictions.filter((v) => v > mhhw).length;
  const below = station.predictions.filter((v) => v < mllw).length;
  return {
    form,
    type,
    spring: 2 * (m2.amplitude + s2.amplitude),
    neap: 2 * (m2.amplitude - s2.amplitude),
    mhhw,
    mllw,
    mhw,
    mlw,
    mtl: (mhw + mlw) / 2,
    dtl: (mhhw + mllw) / 2,
    mn: mhw - mlw,
    gt: mhhw - mllw,
    hat: station.model.mean + amplitudes,
    lat: station.model.mean - amplitudes,
    highest: choose(station.highs, (e) => e.height)!,
    lowest: choose(station.lows, (e) => e.height, false)!,
    widest: choose(complete, (d) => d.range!)!,
    narrowest: choose(complete, (d) => d.range!, false)!,
    above: (100 * above) / (params.hours + 1),
    below: (100 * below) / (params.hours + 1),
    rise: mean(rises),
    fall: mean(falls),
    m4Ratio: m4.amplitude / m2.amplitude,
    relativePhase,
    dominance: relativePhase < 180 ? 'flood' : 'ebb',
  };
}
function springNeap(station: Fitted, params: Parameters) {
  const m2 = station.fittedConstituents.get('M2')!;
  const s2 = station.fittedConstituents.get('S2')!;
  const dw = s2.speed - m2.speed;
  const dg = s2.phase - m2.phase;
  const qa = (dw * params.start - dg) / 180;
  const qb = (dw * (params.start + params.hours) - dg) / 180;
  const events: { type: string; minute: number }[] = [];
  for (let q = Math.floor(Math.min(qa, qb)) - 1; q <= Math.ceil(Math.max(qa, qb)) + 1; q++) {
    const time = (dg + 180 * q) / dw;
    if (params.start <= time && time <= params.start + params.hours) {
      events.push({ type: q % 2 === 0 ? 'spring' : 'neap', minute: Math.floor(time * 60 + 0.5) });
    }
  }
  return events;
}
function analyzeStation(
  source: Station,
  rows: Observation[],
  constituents: Constituent[],
  params: Parameters,
) {
  const station = predictions(
    finalFit(checkStation(source, rows, constituents, params), params),
    params,
  );
  return {
    ...station,
    validation: validation(station, constituents, params),
    events: residualEvents(station, params.surge),
    dailyMeans: dailyMeans(station),
    characteristics: tidalCharacteristics(station, params),
    springNeap: springNeap(station, params),
  };
}
function cleaningLines(s: StationResult, p: Parameters): string[] {
  const dt = (t: number): string => hourDatetime(p.epoch, t);
  const c = s.counts;
  const lines = [
    `station=${s.code} name=${s.name}`,
    `span start=${dt(s.first)} end=${dt(s.last)} hours=${s.length + 1} record_length=${s.length}`,
    `counts rows=${c.rows} numeric=${c.numeric} na=${c.na} absent=${c.absent} flat=${c.flat} spikes=${c.spikes} usable=${c.usable}`,
  ];
  for (const run of s.flats) {
    lines.push(
      `flat start=${dt(run.start)} end=${dt(run.end)} value=${f(run.value, 3)} removed=${run.end - run.start}`,
    );
  }
  lines.push(
    `spike_test window=${p.spike.window} candidates=${s.candidates.length} tested=${s.tested} prefit_rms=${f(s.prefitRms, 4)}`,
  );
  for (const spike of s.spikes) {
    lines.push(
      `spike time=${dt(spike.time)} value=${f(spike.value, 3)} residual=${f(spike.residual, 4)} median=${f(spike.median, 4)} mad=${f(spike.mad, 4)} limit=${f(spike.limit, 4)}`,
    );
  }
  for (const gap of s.gaps) {
    lines.push(
      `gap start=${dt(gap.start)} end=${dt(gap.end)} hours=${gap.end - gap.start + 1} cause=${gap.cause}`,
    );
  }
  return lines;
}
function constituentLines(s: StationResult, constituents: Constituent[]): string[] {
  return constituents.map((c) => {
    const status = s.selection.statuses.get(c.name)!;
    const prefix = `${s.code},${c.name},${f(c.speed, 7)},${status}`;
    if (status !== 'fitted') return prefix + ',,,,,,';
    const x = s.fittedConstituents.get(c.name)!;
    return (
      prefix +
      `,${f(x.amplitude, 4)},${f(x.phase, 2)},${f(x.amplitudeError, 4)},${f(x.phaseError, 2)},${f(x.snr, 1)},${x.significant}`
    );
  });
}
function extremeLines(s: StationResult, p: Parameters): string[] {
  const lines = [
    `station=${s.code} extremes=${s.extrema.length} raw=${s.rawExtrema} removed=${s.rawExtrema - s.extrema.length}`,
  ];
  s.extrema.forEach((e, i) =>
    lines.push(
      `${datetime(p.epoch, e.minute)} ${e.label} ${f(e.height, 3)} change=${i ? f(e.height - s.extrema[i - 1].height, 3) : 'none'}`,
    ),
  );
  for (const d of s.daily) {
    lines.push(
      `day date=${date(p.epoch, d.day)} high_waters=${d.highCount} low_waters=${d.lowCount} hhw=${f(d.hhw, 3)} llw=${f(d.llw, 3)} range=${f(d.range, 3)}`,
    );
  }
  return lines;
}
function summaryLines(s: StationResult, p: Parameters): string[] {
