    `datums mhhw=${f(t.mhhw, 3)} mhw=${f(t.mhw, 3)} mtl=${f(t.mtl, 3)} dtl=${f(t.dtl, 3)} mlw=${f(t.mlw, 3)} mllw=${f(t.mllw, 3)}`,
    `bounds hat=${f(t.hat, 3)} lat=${f(t.lat, 3)}`,
    `window high_waters=${s.highs.length} low_waters=${s.lows.length} highest=${f(t.highest.height, 3)} highest_time=${minute(t.highest.minute)} lowest=${f(t.lowest.height, 3)} lowest_time=${minute(t.lowest.minute)}`,
    `daily_range widest=${f(t.widest.range, 3)} widest_date=${day(t.widest.day)} narrowest=${f(t.narrowest.range, 3)} narrowest_date=${day(t.narrowest.day)}`,
    `exceedance above_mhhw=${f(t.above, 2)} below_mllw=${f(t.below, 2)}`,
  );
  for (const event of s.springNeap) lines.push(`${event.type} time=${minute(event.minute)}`);
  lines.push(
    `surges count=${s.events.length} threshold=${f(p.surge.threshold, 3)} min_hours=${p.surge.hours}`,
  );
  for (const e of s.events) {
    lines.push(
      `surge type=${e.type} start=${dt(e.start)} end=${dt(e.end)} hours=${e.end - e.start + 1} peak=${f(e.peak, 4)} peak_time=${dt(e.peakTime)}`,
    );
  }
  lines.push(
    `daily_mean days=${d.days.length} average=${f(d.average, 4)} slope_mm_per_day=${f(d.slope, 3)} max=${f(d.maximum.level, 4)} max_date=${day(d.maximum.day)} min=${f(d.minimum.level, 4)} min_date=${day(d.minimum.day)}`,
  );
  for (const entry of d.days) {
    lines.push(
      `daily_mean date=${day(entry.day)} level=${f(entry.level, 4)} filled=${entry.filled}`,
    );
  }
  return lines;
}
function waterLag(waters: Extremum[], reference: Extremum[]): number {
  let total = 0;
  for (const water of waters) {
    let nearest = reference[0];
    for (let i = 1; i < reference.length; i++) {
      if (Math.abs(reference[i].minute - water.minute) < Math.abs(nearest.minute - water.minute)) {
        nearest = reference[i];
      }
    }
    total += water.minute - nearest.minute;
  }
  return total / waters.length;
}
function comparisonLines(stations: StationResult[], p: Parameters): string[] {
  const reference = stations.find((s) => s.code === p.reference)!;
  const lines = [`[comparison] reference=${p.reference}`];
  for (const s of stations) {
    if (s === reference) continue;
    lines.push(
      `${s.code} tide hw_lag_min=${f(waterLag(s.highs, reference.highs), 1)} lw_lag_min=${f(waterLag(s.lows, reference.lows), 1)} range_ratio=${f(s.characteristics.gt / reference.characteristics.gt, 4)} mtl_diff=${f(s.characteristics.mtl - reference.characteristics.mtl, 3)}`,
    );
    for (const name of ['M2', 'S2', 'K1', 'O1']) {
      const own = s.fittedConstituents.get(name)!;
      const other = reference.fittedConstituents.get(name)!;
      let phase = own.phase - other.phase;
      if (phase > 180) phase -= 360;
      if (phase <= -180) phase += 360;
      lines.push(
        `${s.code} ${name} amplitude_ratio=${f(own.amplitude / other.amplitude, 4)} phase_diff=${f(phase, 2)} time_lag_min=${f((phase / own.speed) * 60, 1)}`,
      );
    }
  }
  return lines;
}
function correlation(a: StationResult, b: StationResult, lag: number) {
  const pairs: [number, number][] = [];
  for (const row of a.usable) {
    if (b.residuals.has(row.time + lag)) {
      pairs.push([row.residual, b.residuals.get(row.time + lag)!]);
    }
  }
  const mx = mean(pairs.map((pair) => pair[0]));
  const my = mean(pairs.map((pair) => pair[1]));
  let sxy = 0;
  let sxx = 0;
  let syy = 0;
  for (const pair of pairs) {
    const x = pair[0] - mx;
    const y = pair[1] - my;
    sxy += x * y;
    sxx += x * x;
    syy += y * y;
  }
  return { lag, rho: sxy / Math.sqrt(sxx * syy), pairs: pairs.length };
}
function correlationLines(stations: StationResult[], maximum: number): string[] {
  const lines = [`[correlation] max_lag=${maximum}`];
  for (let i = 0; i < stations.length; i++) {
    for (let j = i + 1; j < stations.length; j++) {
      let best: ReturnType<typeof correlation> | null = null;
      let zero = 0;
      for (let lag = -maximum; lag <= maximum; lag++) {
        const c = correlation(stations[i], stations[j], lag);
        if (lag === 0) zero = c.rho;
        if (
          best === null ||
          c.rho > best.rho ||
          (c.rho === best.rho &&
            (Math.abs(lag) < Math.abs(best.lag) ||
              (Math.abs(lag) === Math.abs(best.lag) && lag < best.lag)))
        ) {
          best = c;
        }
      }
      lines.push(
        `${stations[i].code}-${stations[j].code} lag0=${f(zero, 4)} best_lag=${best!.lag} best=${f(best!.rho, 4)} pairs=${best!.pairs}`,
      );
    }
  }
  return lines;
}
function plot(stations: StationResult[], p: Parameters): string[] {
  const s = stations.find((s) => s.code === p.plot.code)!;
  const { hours, top, bottom, step } = p.plot;
  const rows = (top - bottom) / step + 1;
  const cells: string[][] = Array.from({ length: rows }, () => Array(hours).fill(' '));
  const heights = Array.from({ length: rows }, (_, r) => top - r * step);
  const baseline = Math.floor((top - 100 * s.model.mean) / step + 0.5);
  if (baseline >= 0 && baseline < rows) cells[baseline].fill('-');
  const marks = new Map<number, string>();
  for (const e of s.extrema) {
    const column = Math.floor((e.minute - 60 * p.start + 30) / 60);
    if (column >= 0 && column < hours) marks.set(column, e.kind === 'high' ? 'H' : 'L');
  }
  for (let c = 0; c < hours; c++) {
    const row = Math.floor((top - 100 * s.predictions[c]) / step + 0.5);
    if (row < 0) cells[0][c] = '^';
    else if (row >= rows) cells[rows - 1][c] = 'v';
    else cells[row][c] = marks.get(c) ?? '*';
  }
  return [
    `[plot] station=${s.code} start=${hourDatetime(p.epoch, p.start)} hours=${hours} step_cm=${step}`,
    ...plotLines(cells, heights),
  ];
}
function main(): void {
  const { params, constituents, observations } = readAll();
  const stations = params.stations.map((s) =>
    analyzeStation(s, observations.get(s.code)!, constituents, params),
  );
  const cleaning: string[] = [];
  const constants = [
    'station,constituent,speed,status,amplitude,phase,amplitude_error,phase_error,snr,significant',
  ];
  const extremes: string[] = [];
  const summary: string[] = [];
  const predictions = ['time,' + params.stations.map((s) => s.code).join(',')];
  for (const s of stations) {
    cleaning.push(...cleaningLines(s, params));
    constants.push(...constituentLines(s, constituents));
    extremes.push(...extremeLines(s, params));
    summary.push(...summaryLines(s, params));
  }
  for (let i = 0; i <= params.hours; i++) {
    predictions.push(
      hourDatetime(params.epoch, params.start + i) +
        ',' +
        stations.map((s) => f(s.predictions[i], 3)).join(','),
    );
  }
  summary.push(
    ...comparisonLines(stations, params),
    ...correlationLines(stations, params.correlationLag),
    ...plot(stations, params),
  );
  writeFiles({
    'cleaning.txt': cleaning,
    'constituents.csv': constants,
    'predictions.csv': predictions,
    'extremes.txt': extremes,
    'summary.txt': summary,
  });
}
main();

import { angle, type Model } from './harmonic_fit.ts';

export interface GridExtremum {
  kind: 'high' | 'low';
  refinedMinute: number;
  height: number;
}
export function level(model: Model, time: number): number {
  let value = model.mean;
  for (const c of model.constituents) {
    const theta = angle(c.speed, time);
    value += c.a * Math.cos(theta) + c.b * Math.sin(theta);
  }
  return value;
}
export function gridExtrema(
  model: Model,
  start: number,
  hours: number,
  spacing: number,
): GridExtremum[] {
  const count = (hours * 60) / spacing;
  const values = Array.from({ length: count + 1 }, (_, j) =>
    level(model, (60 * start + j * spacing) / 60),
  );
  const extrema: GridExtremum[] = [];
  for (let j = 1; j < count; j++) {
    const previous = values[j - 1];
    const current = values[j];
    const next = values[j + 1];
    let kind: GridExtremum['kind'];
    if (previous < current && current > next) kind = 'high';
    else if (previous > current && current < next) kind = 'low';
    else continue;
    const delta = (previous - next) / (2 * (previous - 2 * current + next));
    extrema.push({
      kind,
      refinedMinute: 60 * start + j * spacing + delta * spacing,
      height: current - ((previous - next) * delta) / 4,
    });
  }
  return extrema;
}

import { readFileSync } from 'node:fs';

export interface Station {
  code: string;
  name: string;
}
export interface Constituent {
  name: string;
  speed: number;
}
export interface Observation {
  time: number;
  value: number | null;
  milli: number | null;
}
export interface NumericRow {
  time: number;
  value: number;
  milli: number;
}
export interface SpikeSettings {
  window: number;
  count: number;
  factor: number;
  minimum: number;
}
export interface Parameters {
  epoch: number;
  stations: Station[];
  reference: string;
  flatRun: number;
  spike: SpikeSettings;
  rayleigh: number;
  snrMin: number;
  topResiduals: number;
  surge: { threshold: number; hours: number };
  start: number;
  hours: number;
  grid: number;
  minRange: number;
  correlationLag: number;
  plot: { code: string; hours: number; top: number; bottom: number; step: number };
}
const lines = (path: string): string[] => readFileSync(path, 'ascii').trimEnd().split('\n');
const absoluteMinute = (value: string): number =>
  Date.parse(value.replace(' ', 'T') + ':00Z') / 60000;
export const datetime = (epoch: number, minute: number): string =>
  new Date((epoch + minute) * 60000).toISOString().slice(0, 16).replace('T', ' ');
export const hourDatetime = (epoch: number, hour: number): string => datetime(epoch, hour * 60);
export const date = (epoch: number, day: number): string =>
  datetime(epoch, day * 1440).slice(0, 10);
function readParameters(): Parameters {
  const source = lines('input/params.txt');
  const epoch = absoluteMinute(source[0].slice(6));
  const stations: Station[] = [];
  let i = 1;
  while (source[i].startsWith('station ')) {
    stations.push({ code: source[i].slice(8, 11), name: source[i].slice(12) });
    i++;
  }
  const next = (): string[] => source[i++].split(' ');
  const reference = next()[1];
  const flatRun = Number(next()[1]);
  const s = next();
  const spike = {
    window: Number(s[1]),
    count: Number(s[2]),
    factor: Number(s[3]),
    minimum: Number(s[4]),
  };
  const rayleigh = Number(next()[1]);
  const snrMin = Number(next()[1]);
  const topResiduals = Number(next()[1]);
  const surgeRow = next();
  const surge = { threshold: Number(surgeRow[1]), hours: Number(surgeRow[2]) };
  const prediction = next();
  const start = (absoluteMinute(prediction[1] + ' ' + prediction[2]) - epoch) / 60;
  const hours = Number(prediction[3]);
  const grid = Number(next()[1]);
  const minRange = Number(next()[1]);
  const correlationLag = Number(next()[1]);
  const plotRow = next();
  const plot = {
    code: plotRow[1],
    hours: Number(plotRow[2]),
    top: Number(plotRow[3]),
    bottom: Number(plotRow[4]),
    step: Number(plotRow[5]),
  };
  return {
    epoch,
    stations,
    reference,
    flatRun,
    spike,
    rayleigh,
    snrMin,
    topResiduals,
    surge,
    start,
    hours,
    grid,
    minRange,
    correlationLag,
    plot,
  };
}
export function readAll(): {
  params: Parameters;
  constituents: Constituent[];
  observations: Map<string, Observation[]>;
} {
  const params = readParameters();
  const rows = lines('input/constituents.txt');
  const constituents = rows.slice(1, Number(rows[0]) + 1).map((line) => {
    const [name, speed] = line.split(' ');
    return { name, speed: Number(speed) };
  });
  const observations = new Map<string, Observation[]>(params.stations.map((s) => [s.code, []]));
  for (const line of lines('input/observations.csv').slice(1)) {
    const [code, time, level] = line.split(',');
    observations.get(code)!.push({
      time: (absoluteMinute(time) - params.epoch) / 60,
      value: level === 'NA' ? null : Number(level),
      milli: level === 'NA' ? null : Number(level.replace('.', '')),
    });
  }
  return { params, constituents, observations };
}

import { mkdirSync, writeFileSync } from 'node:fs';

export function real(value: number | null, digits: number): string {
  if (value === null) return 'none';
  if (Math.abs(value) >= 1e21) {
    return BigInt(value).toString() + (digits ? '.' + '0'.repeat(digits) : '');
  }
  const text = value.toFixed(digits);
  return Number(text) === 0 ? (0).toFixed(digits) : text;
}
export function plotLines(cells: string[][], heights: number[]): string[] {
  const labels = heights.map((h) => real(h / 100, 2));
  const width = Math.max(...labels.map((s) => s.length));
  return [
    ...cells.map((row, i) => labels[i].padStart(width) + ' |' + row.join('') + '|'),
    ' '.repeat(width) + ' +' + cells[0].map((_, c) => (c % 6 === 0 ? '+' : '-')).join('') + '+',
  ];
}
export function writeFiles(files: Record<string, string[]>): void {
  mkdirSync('output', { recursive: true });
  for (const [name, lines] of Object.entries(files)) {
    writeFileSync('output/' + name, lines.join('\n') + '\n', 'ascii');
  }
}
